    var str = pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' ');
    var pl = g.polyline(str).fill('none')
      .stroke({ color: BASE, width: 2, linejoin: 'round', linecap: 'round' });
    var hs = [];
    (arrows || []).forEach(function (a) { hs.push(head(g, a[0], a[1], a[2])); });
    g.polyline(str).fill('none').stroke({ color: '#000', width: 16, opacity: 0 });
