// @FIGURE_CODE_BEGIN
(function () {
  var W = 1180, H = 450;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var BASE = '#111111';
  var HOT = '#1a6fd4';
  var HOVER = '#49a3ff';
  var RED = '#d62728';
  var GREEN = '#1a9850';
  var SERIF = 'Georgia,"Times New Roman",serif';
  var MONO = 'ui-monospace,Consolas,"Courier New",monospace';

  var yCh = 330, yBox = 150;

  /* ---------- text helpers ---------- */
  function halo(el, w) {
    el.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': w || 4, 'stroke-linejoin': 'round' });
    return el;
  }
  function plain(parent, str, x, y, size, opts) {
    opts = opts || {};
    var t = parent.plain(str)
      .font({ family: opts.mono ? MONO : SERIF, size: size, style: opts.italic ? 'italic' : 'normal' })
      .fill(opts.color || BASE)
      .attr({ x: x, y: y, 'text-anchor': opts.anchor || 'start' });
    if (opts.halo) halo(t, opts.halo);
    return t;
  }
  // parts: [{t:'S', it:true, sub:false}, ...]
  function rich(parent, parts, x, y, size, color, align, haloW) {
    var grp = parent.group();
    var cx = 0;
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i];
      var fs = size * (p.sub ? 0.68 : 1);
      var t = grp.plain(p.t)
        .font({ family: SERIF, size: fs, style: p.it ? 'italic' : 'normal' })
        .fill(color || BASE)
        .attr({ x: cx, y: p.sub ? size * 0.26 : 0 });
      if (haloW) halo(t, haloW);
      cx += t.bbox().width + (p.pad || 0);
    }
    var dx = align === 'middle' ? -cx / 2 : (align === 'end' ? -cx : 0);
    grp.attr('transform', 'translate(' + (x + dx) + ',' + y + ')');
    return grp;
  }

  /* ---------- segment helpers ---------- */
  var segs = {};
  function head(g, x, y, dir) {
    var L = 15, Wd = 6, p;
    if (dir === 'r') p = [[x, y], [x - L, y - Wd], [x - L, y + Wd]];
    else if (dir === 'l') p = [[x, y], [x + L, y - Wd], [x + L, y + Wd]];
    else if (dir === 'd') p = [[x, y], [x - Wd, y - L], [x + Wd, y - L]];
    else p = [[x, y], [x - Wd, y + L], [x + Wd, y + L]];
    return g.polygon(p.map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(BASE).stroke('none');
  }
  function addSeg(name, pts, arrows) {
    var g = draw.group();
    var str = pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' ');
    var pl = g.polyline(str).fill('none')
      .stroke({ color: BASE, width: 2.2, linejoin: 'round', linecap: 'round' });
    var hs = [];
    (arrows || []).forEach(function (a) { hs.push(head(g, a[0], a[1], a[2])); });
    g.polyline(str).fill('none').stroke({ color: '#000', width: 16, opacity: 0 });
    segs[name] = { g: g, pl: pl, heads: hs };
    return segs[name];
  }
  function paint(name, color, width) {
    var s = segs[name];
    if (!s) return;
    s.pl.stroke({ color: color, width: width });
    s.heads.forEach(function (h) { h.fill(color); });
  }

  /* ---------- geometry ---------- */
  addSeg('msgIn', [[60, yCh], [120, yCh]]);
  addSeg('riserA', [[120, yCh], [120, yBox], [160, yBox]], [[170, yBox, 'r']]);
  addSeg('chanA', [[120, yCh], [430, yCh]]);
  addSeg('sigWire', [[262, yBox], [430, yBox], [430, 318]], [[430, yCh, 'd']]);
  addSeg('chanPair', [[430, yCh], [800, yCh]]);
  addSeg('riserB', [[800, yCh], [800, yBox], [835, yBox]], [[845, yBox, 'r']]);
  addSeg('chanB', [[800, yCh], [990, yCh], [990, 280]], [[990, 266, 'u']]);
  addSeg('pOut', [[940, yBox], [990, yBox], [990, 208]], [[990, 222, 'd']]);
  addSeg('accArrow', [[1023, 244], [1050, 244]], [[1062, 244, 'r']]);

  function mkBox(x, y, w, h, parts, size) {
    var g = draw.group();
    var r = g.rect(w, h).move(x, y).fill('#d4d4d4').stroke({ color: BASE, width: 2.2 });
    var lbl = rich(g, parts, x + w / 2, y + h / 2 + size * 0.34, size, BASE, 'middle');
    return { g: g, rect: r, label: lbl };
  }
  var boxS = mkBox(170, 117, 92, 66, [{ t: 'S', it: true }, { t: 'A', it: true, sub: true }], 29);
  var boxP = mkBox(845, 117, 95, 66, [{ t: 'P', it: true }, { t: 'A', it: true, sub: true }], 29);
  var boxEq = mkBox(957, 222, 66, 44, [{ t: '=?' }], 25);

  /* ---------- static labels ---------- */
  plain(draw, 'Alice', 216, 48, 31, { anchor: 'middle' });
  plain(draw, 'Bob', 940, 48, 31, { anchor: 'middle' });
  plain(draw, 'sign', 216, 105, 27, { anchor: 'middle' });
  plain(draw, 'verify', 892, 105, 27, { anchor: 'middle' });
  rich(draw, [{ t: 'M', it: true }, { t: '\u2032' }], 50, 338, 28, BASE, 'end');
  rich(draw, [{ t: '\u03C3 = S', it: true }, { t: 'A', it: true, sub: true }, { t: '(M', it: true }, { t: '\u2032)', it: true }],
    274, 136, 27, BASE, 'start', 4);
  plain(draw, '\u03C3', 790, 138, 27, { anchor: 'end', italic: true, halo: 4 });
  rich(draw, [{ t: '(M', it: true }, { t: '\u2032, \u03C3)', it: true }], 600, 310, 27, BASE, 'middle', 4);
  rich(draw, [{ t: 'M', it: true }, { t: '\u2032' }], 900, 310, 27, BASE, 'middle', 4);
  plain(draw, 'communication channel', 600, 404, 27, { anchor: 'middle' });

  var dyn = draw.group();

  /* ---------- state ---------- */
  var STAGES = ['idle', 'sign', 'transmit', 'verify', 'compare'];
  var stage = 0;
  var tamper = 'none'; // none | msg | sig

  var MSG = 'HELLO', SIG = '4f2a';
  function recvMsg() { return tamper === 'msg' ? 'HELL0' : MSG; }
  function recvSig() { return tamper === 'sig' ? '9c71' : SIG; }
  function paSig() { return tamper === 'sig' ? 'Zq7#m' : MSG; }
  function accepts() { return paSig() === recvMsg(); }

  var hovered = null;

  function badge(x, y, str, color, anchor, size) {
    var t = dyn.plain(str)
      .font({ family: MONO, size: size || 17 })
      .fill(color || '#333')
      .attr({ x: x, y: y, 'text-anchor': anchor || 'middle' });
    var b = t.bbox();
    dyn.rect(b.width + 10, b.height + 4).move(b.x - 5, b.y - 2)
      .fill('#ffffff').opacity(0.94).radius(3).back();
    return t;
  }

  function setBox(bx, on, okColor) {
    if (on) {
      bx.rect.fill(okColor ? (okColor === GREEN ? '#d8f0de' : '#fadddd') : '#cfe3f7')
        .stroke({ color: okColor || HOT, width: 3 });
    } else {
      bx.rect.fill('#d4d4d4').stroke({ color: BASE, width: 2.2 });
    }
  }

  function render() {
    Object.keys(segs).forEach(function (k) { paint(k, BASE, 2.2); });
    var hot = [];
    if (stage >= 1) hot.push('msgIn', 'riserA', 'sigWire');
    if (stage >= 2) hot.push('chanA', 'chanPair');
    if (stage >= 3) hot.push('riserB');
    if (stage >= 4) hot.push('pOut', 'chanB', 'accArrow');
    hot.forEach(function (k) { paint(k, HOT, 3.6); });

    var ok = accepts();
    if (stage >= 2 && tamper !== 'none') paint('chanPair', RED, 3.6);
    if (stage >= 3 && tamper === 'sig') paint('riserB', RED, 3.6);
    if (stage >= 4 && tamper === 'msg') paint('chanB', RED, 3.6);
    if (stage >= 4) paint('accArrow', ok ? GREEN : RED, 3.6);

    setBox(boxS, stage >= 1);
    setBox(boxP, stage >= 3);
    setBox(boxEq, stage >= 4, stage >= 4 ? (ok ? GREEN : RED) : null);

    if (hovered && segs[hovered]) paint(hovered, HOVER, 4);

    dyn.clear();

    // Concrete value badges appear only once the protocol has started.
    if (stage >= 1) {
      badge(250, 360, "M\u2032 = " + MSG, HOT);
      badge(444, 202, "\u03C3 = " + SIG, HOT, 'start');
    }
    if (stage >= 2) {
      var pc = (tamper === 'none') ? HOT : RED;
      badge(560, 364, "M\u2032=" + recvMsg() + "  \u03C3=" + recvSig(), pc);
      if (tamper !== 'none') {
        halo(dyn.plain('\u2716').font({ family: SERIF, size: 24 }).fill(RED)
          .attr({ x: 700, y: 339, 'text-anchor': 'middle' }), 5);
        badge(716, 284, tamper === 'msg' ? 'message altered' : 'signature forged', RED, 'middle', 15);
      }
    }
    if (stage >= 3) badge(790, 202, "\u03C3 = " + recvSig(), tamper === 'sig' ? RED : HOT, 'end');
    if (stage >= 4) {
      badge(982, 212, "P\u2090(\u03C3) = " + paSig(), tamper === 'sig' ? RED : HOT, 'end');
      badge(900, 364, "M\u2032 = " + recvMsg(), tamper === 'msg' ? RED : HOT);
    }

    var verdict = stage >= 4 ? (ok ? 'accept' : 'reject') : 'accept';
    var vcol = stage >= 4 ? (ok ? GREEN : RED) : BASE;
    dyn.plain(verdict).font({ family: SERIF, size: 28 }).fill(vcol)
      .attr({ x: 1072, y: 254, 'text-anchor': 'start' });

    document.getElementById('protocolStepVal').value = STAGES[stage];
    var vl = document.getElementById('verdictLine');
    if (stage < 4) {
      vl.innerHTML = 'Comparison not reached yet.';
    } else if (ok) {
      vl.innerHTML = '<b style="color:#1a9850">P_A(\u03C3) = M\u2032 \u2192 accept</b>';
    } else {
      vl.innerHTML = '<b style="color:#d62728">P_A(\u03C3) \u2260 M\u2032 \u2192 reject</b>';
    }
  }

  /* ---------- hover / click ---------- */
  function hoverSeg(name, tip, title, body) {
    var s = segs[name];
    s.g.css('cursor', 'pointer');
    s.g.on('mousemove', function (e) { showTooltip(tip, e); });
    s.g.on('mouseenter', function () { hovered = name; render(); });
    s.g.on('mouseleave', function () { hovered = null; render(); hideTooltip(); });
    if (title) s.g.on('click', function () { showPopup(title, body); });
  }
  function hoverBox(bx, tip, title, body) {
    bx.g.css('cursor', 'pointer');
    bx.g.on('mousemove', function (e) { showTooltip(tip, e); });
    bx.g.on('mouseleave', function () { hideTooltip(); });
    bx.g.on('click', function () { showPopup(title, body); });
  }

  hoverSeg('msgIn', "The plaintext message M\u2032 enters the channel.", 'The message',
    "M\u2032 is sent in the clear. A digital signature provides authenticity and integrity, not secrecy.");
  hoverSeg('riserA', "A copy of M\u2032 branches up into the signer.", 'Signing branch',
    "The message itself is not modified. A copy is fed into S_A, which produces a separate value \u03C3 that will travel alongside the message.");
  hoverSeg('sigWire', "\u03C3 = S_A(M\u2032) drops back onto the channel.", 'Signature joins the channel',
    "The signature is appended to the message, so from this junction on the channel carries the pair (M\u2032, \u03C3) in the clear \u2014 nothing here is encrypted.");
  hoverSeg('chanPair', "The channel carries the pair (M\u2032, \u03C3).", 'Public channel',
    "Anyone can read \u2014 and try to modify \u2014 both halves of the pair while it is in transit. Security comes from verification, not from hiding the data.");
  hoverSeg('riserB', "Only \u03C3 needs the public transform P_A.", 'Why \u03C3 goes through P_A',
    "The signature is an encoded form of the message. P_A, Alice's public key transform, is the only operation that turns \u03C3 back into a candidate message. The received M\u2032 is already a message, so it goes straight to the comparator.");
  hoverSeg('chanB', "The received M\u2032 goes straight to the comparator.", 'Message branch',
    "No transform is applied to the received message. It is one of the two things being compared; the other is P_A(\u03C3).");
  hoverSeg('pOut', "P_A(\u03C3): the message recovered from the signature.", 'Recovered message',
    "This wire carries the candidate message that the signature encodes. It enters the comparison box from above.");
  hoverSeg('accArrow', "Result of the equality test.", 'Accept / reject',
    "The comparator emits accept only when the two inputs are identical strings. Any mismatch \u2014 in the message or in the signature \u2014 produces a reject.");
  hoverBox(boxS, "S_A: Alice's SECRET signing transform.", "S_A \u2014 secret key",
    "Only Alice can compute S_A. This is what makes the signature unforgeable: an adversary can copy or alter bits, but cannot produce a new \u03C3 whose public transform lands on a chosen message.");
  hoverBox(boxP, "P_A: Alice's PUBLIC verification transform.", "P_A \u2014 public key",
    "P_A is published, so anybody \u2014 not just Bob \u2014 can verify. Verification involves no secrets at all: it is a public transform followed by an equality test.");
  hoverBox(boxEq, "=? compares P_A(\u03C3) with the received M\u2032.", 'The equality test',
    "The box receives P_A(\u03C3) from above and the received M\u2032 from below. Bob accepts precisely when these two independently obtained copies of the message agree.");

  /* ---------- controls ---------- */
  window.trigger_protocolStep = function () { stage = (stage + 1) % STAGES.length; render(); };
  window.reset_protocol = function () { stage = 0; render(); };
  window.toggle_tamper = function (v) {
    tamper = (v === "tampered message M'") ? 'msg' : (v === 'tampered signature sigma' ? 'sig' : 'none');
    render();
  };
  function setStageByName(n) { var i = STAGES.indexOf(n); stage = i < 0 ? 0 : i; }
  function setTamperByName(v) {
    document.getElementById('tamperInput').value = v;
    tamper = (v === "tampered message M'") ? 'msg' : (v === 'tampered signature sigma' ? 'sig' : 'none');
  }

  /* ---------- demo player ---------- */
  var demoSteps = [
    { title: 'The message enters the channel', narration: "Alice's message M\u2032 arrives at the left of the communication channel. Nothing is signed yet \u2014 the diagram is idle.", state: { protocolStep: 'idle', tamper: 'untampered' } },
    { title: 'Alice signs', narration: "A branch of M\u2032 rises into the shaded box S_A, Alice's secret signing transform. Its output \u03C3 = S_A(M\u2032) lights up along the top wire.", state: { protocolStep: 'sign', tamper: 'untampered' } },
    { title: 'The pair travels', narration: "Sigma drops back onto the channel, which from this junction carries the pair (M\u2032, \u03C3). Both halves travel in the clear toward Bob.", state: { protocolStep: 'transmit', tamper: 'untampered' } },
    { title: 'Bob verifies with the public key', narration: "At Bob's side the pair splits: \u03C3 branches up into P_A, Alice's public verification transform, which recovers a candidate message from the signature.", state: { protocolStep: 'verify', tamper: 'untampered' } },
